```c++
#include <iostream>
#include <stdlib.h>

using namespace std;

struct Node {
  int data;
  Node* next;
};

class LinkedList {
private:
  Node* head;

public:
  LinkedList() : head(nullptr) {}

  void addNode(int data) {
    Node* newNode = new Node{data, head};
    head = newNode;
  }

  void printList() {
    Node* current = head;
    while (current) {
      cout << current->data << " ";
      current = current->next;
    }
    cout << endl;
  }
};

int main() {
  LinkedList* linkedList = new LinkedList();

  linkedList->addNode(1);
  linkedList->addNode(2);
  linkedList->addNode(3);
  linkedList->addNode(4);
  linkedList->addNode(5);

  linkedList->printList();

  delete linkedList;

  return 0;
}
```

**Explanation:**

* The `Node` structure stores the data and a pointer to the next node.
* The `LinkedList` class contains a pointer to the head node.
* `addNode` adds a new node to the end of the linked list.
* `printList` iterates through the list and prints the data of each node.
* `delete` releases the memory allocated for the linked list.

**Output:**

```
1 2 3 4 5
```

**Note:**

* The code can be extended to include functions for searching, deleting, and manipulating specific nodes in the linked list.
* You can also use smart pointers to automatically manage memory allocation and deallocation.

